function isoUTC(d){return `${d.getUTCFullYear()}-${String(d.getUTCMonth()+1).padStart(2,'0')}-${String(d.getUTCDate()).padStart(2,'0')}`}
function parseISODate(s){let m=String(s||'').match(/^(\d{4})-(\d{2})-(\d{2})$/);if(!m)return null;let d=new Date(Date.UTC(Number(m[1]),Number(m[2])-1,Number(m[3])));return Number.isNaN(d.getTime())?null:d}
function easterSunday(year){let a=year%19,b=Math.floor(year/100),c=year%100,d=Math.floor(b/4),e=b%4,f=Math.floor((b+8)/25),g=Math.floor((b-f+1)/3),h=(19*a+b-d-g+15)%30,i=Math.floor(c/4),k=c%4,l=(32+2*e+2*i-h-k)%7,m=Math.floor((a+11*h+22*l)/451),month=Math.floor((h+l-7*m+114)/31),day=((h+l-7*m+114)%31)+1;return new Date(Date.UTC(year,month-1,day))}
function costaRicaHolidays(year){let fixed=[[1,1],[4,11],[5,1],[7,25],[8,2],[8,15],[8,31],[9,15],[12,1],[12,25]],set=new Set(fixed.map(([m,d])=>`${year}-${String(m).padStart(2,'0')}-${String(d).padStart(2,'0')}`)),e=easterSunday(year);for(const delta of [-3,-2]){let x=new Date(e);x.setUTCDate(x.getUTCDate()+delta);set.add(isoUTC(x))}return set}
function isCRBusinessDay(d){let day=d.getUTCDay();if(day===0||day===6)return false;return !costaRicaHolidays(d.getUTCFullYear()).has(isoUTC(d))}
function businessDaysSince(start,endDate){let startD=parseISODate(start);if(!startD)return null;let end=endDate instanceof Date?new Date(Date.UTC(endDate.getFullYear(),endDate.getMonth(),endDate.getDate())):parseISODate(endDate);if(!end)end=new Date();if(end.getTime()<=startD.getTime())return 0;let n=0,d=new Date(startD);d.setUTCDate(d.getUTCDate()+1);while(d<=end){if(isCRBusinessDay(d))n++;d.setUTCDate(d.getUTCDate()+1)}return n}
function ageInfo(e,endDate){let days=businessDaysSince(e?.fecha,endDate);if(days===null)return {days:null,className:'',label:'Sin fecha'};if(days>=15)return {days,className:'red',rowClass:'aging-red',label:`${days} días hábiles`};if(days>10)return {days,className:'yellow',rowClass:'aging-yellow',label:`${days} días hábiles`};return {days,className:'blue',rowClass:'',label:`${days} días hábiles`}}
function matchesAlertFilter(e,value){let v=String(value||'').toUpperCase(),d=ageInfo(e).days;if(!v)return true;if(v==='ALARMAS')return d!==null&&d>10;if(v==='SIN_ALARMAS')return d===null||d<=10;if(v==='VENCIMIENTOS')return d!==null&&d>=15;return true}
function statusPill(e){let c=e.estado?.includes('ARCHIVADO')?'amber':e.finalizado?'green':e.estado?.includes('RECHAZADO')?'red':e.estado?.includes('INSPE')?'amber':e.estado?.includes('CALIFIC')?'blue':'amber';return `<span class="pill ${c}">${esc(e.estado||'REGISTRADO')}</span>`}function renderAll(){expedientes.forEach(e=>{normalizeCase(e);if(CVISADOS_WORKFLOW.isTramitesCase(e))updateDecision(e)});renderKpis();renderDistrictFilter();renderTable();renderPreSelect();renderInspectionSelect();renderMotorSelect();renderCloseSelect();if(typeof renderGestion==='function')renderGestion();persist()}
function renderKpis(){let total=expedientes.length,pending=expedientes.filter(CVISADOS_WORKFLOW.isTramitesCase).length,managed=expedientes.filter(CVISADOS_WORKFLOW.isManagementCase),rej=managed.filter(x=>x.dictamen==='RECHAZADO').length,apr=managed.filter(x=>x.dictamen==='APROBADO').length;$('kpis').innerHTML=[['Total',total],['Aprobados',apr],['Rechazados',rej],['Pendientes de revisión',pending]].map(x=>`<div class="kpi"><span>${x[0]}</span><b>${x[1]}</b></div>`).join('')}
