function sharedReferenceCount(e,field){let value=field==='presentacion'?(e.presentacion||e.asiento):e[field],key=idNorm(value);if(!key)return 0;return expedientes.filter(x=>idNorm(field==='presentacion'?(x.presentacion||x.asiento):x[field])===key).length}
