function filterDescription(sQ,d,pQ,visible,total,alert=''){let parts=[];if(sQ)parts.push(`búsqueda: ${$('fSearch').value.trim()}`);if(d)parts.push(`distrito: ${d}`);if(pQ)parts.push(`lugar: ${$('fPlace').value.trim()}`);if(alert)parts.push(`alerta: ${$('fAlert')?.selectedOptions?.[0]?.textContent||alert}`);let txt=`${visible} de ${total} visibles`;if(parts.length)txt+=` · ${parts.join(' · ')}`;let el=$('tramitesSummary');if(el)el.textContent=txt}
