Object.values(COND_FIELDS).forEach(id=>{let el=$(id);if(el)el.onchange=savePreCondition});
function loadPre(id){let e=expedientes.find(x=>x.id===Number(id));if(!e)return;currentPre=e.id;$('preIngreso').value=e.ingreso||'Nuevo ingreso';$('preModalidad').value=e.modalidad||'SIMPLE';syncPreConditions(e);renderRequirements()}
function renderRequirements(){let e=expedientes.find(x=>x.id===currentPre);if(!e)return;let groups=requirementGroups(e);$('reqList').innerHTML=groups.map(g=>{let rows=g.rows.map(r=>{let applies=reqApplies(e,r),checked=!!e.pre?.[r.id],mandatory=isMandatory(r);let state=!applies?'<span class="req-state na">NO APLICA</span>':checked?'<span class="req-state ok">CUMPLE</span>':mandatory?'<span class="req-state bad">NO CUMPLE</span>':'<span class="req-state opt">OPCIONAL</span>';return `<div class="req-row ${!applies?'no-aplica':''}"><input type="checkbox" data-req="${esc(r.id)}" ${checked?'checked':''} ${!applies?'disabled':''}><div><div class="req-title">${esc(r.req)}</div><div class="req-meta">${esc(r.id)} · ${esc(r.nivel)}${r.fund?` · ${esc(r.fund)}`:''}</div></div>${state}</div>`}).join('');let statsRows=g.rows.filter(r=>reqApplies(e,r)&&isMandatory(r)),done=statsRows.filter(r=>!!e.pre?.[r.id]).length;return `<details class="accordion" open><summary>${esc(g.title)} <span class="small">${done}/${statsRows.length} obligatorios cumplen</span></summary><div class="accordion-body">${rows||'<div class="empty">Sin requisitos.</div>'}</div></details>`}).join('');$('reqList').querySelectorAll('[data-req]').forEach(c=>c.onchange=()=>{e.pre[c.dataset.req]=c.checked;updateDecision(e);persist();renderRequirements();renderTable();renderMotorSelect()});let s=preStats(e),fails=s.failures;$('preSummary').textContent=s.complete?`CUMPLE · ${s.ok}/${s.total}`:`NO CUMPLE · ${s.ok}/${s.total}`;$('preSummary').className='right pill '+(s.complete?'green':'red');$('preFailureCount').textContent=String(fails.length);$('preFailureCount').className='right pill '+(fails.length?'red':'green');$('preFailures').innerHTML=fails.length?fails.map(r=>`<div class="failure"><b>${esc(r.id)}</b> — ${esc(r.req)}<div class="small">${esc(r.fund||'')}</div></div>`).join(''):'Sin incumplimientos obligatorios.'}

function emptyAccess(){return {tipo:'Calle pública',anchoPlano:null,anchoInspeccion:null,referencia:'ANCHO_TOTAL',desdeLC:null,desdeLCInspeccion:null,observacion:''}}
function accessEval(a){let p=a?.anchoPlano,i=a?.anchoInspeccion,have=p!==null&&p!==''&&i!==null&&i!==''&&Number.isFinite(Number(p))&&Number.isFinite(Number(i));if(!have)return {status:'PENDIENTE',className:'amber',difference:null,complete:false,match:false};let d=Number(i)-Number(p),match=Math.abs(d)<0.01;return {status:match?'COINCIDE':'DIFERENCIA',className:match?'green':'red',difference:Number(d.toFixed(2)),complete:true,match}}
function inspectionEval(e){let arr=e.inspection?.accesos||[],evals=arr.map(accessEval),complete=arr.length>0&&evals.every(x=>x.complete),mismatches=[];evals.forEach((x,i)=>{if(x.complete&&!x.match)mismatches.push({index:i,...x})});return {complete,match:complete&&mismatches.length===0,mismatches,evals}}
function renderInspectionSelect(){let rows=expedientes.filter(CVISADOS_WORKFLOW.isTramitesCase);if(!rows.some(x=>x.id===currentInspection))currentInspection=rows[0]?.id??null;$('inspectionExp').innerHTML=options(rows,currentInspection);if(rows.length)loadInspection(currentInspection);else{$('accessList').innerHTML='<div class="empty">Sin expedientes.</div>';$('inspectionSummary').textContent='PENDIENTE';$('inspectionOverall').textContent='Sin expedientes.'}}
$('inspectionExp').onchange=e=>{currentInspection=Number(e.target.value);loadInspection(currentInspection)};
function loadInspection(id){let e=expedientes.find(x=>x.id===Number(id));if(!e)return;currentInspection=e.id;normalizeCase(e);$('inspectionObs').value=e.inspection.observaciones||'';renderAccesses()}
function addAccess(){let e=expedientes.find(x=>x.id===currentInspection);if(!e)return;e.inspection.accesos.push(emptyAccess());persist();renderAccesses()}
function removeAccess(i){let e=expedientes.find(x=>x.id===currentInspection);if(!e||e.inspection.accesos.length<=1)return;e.inspection.accesos.splice(i,1);updateDecision(e);persist();renderAccesses();renderMotorSelect()}
function toggleLCView(force){showLCFields=typeof force==='boolean'?force:!showLCFields;$('accessList').classList.toggle('show-lc',showLCFields);$('toggleLCBtn').textContent=showLCFields?'Ocultar datos desde L.C.':'Ver datos desde L.C.'}
function setAccess(i,key,value){let e=expedientes.find(x=>x.id===currentInspection);if(!e)return;let a=e.inspection.accesos[i];if(!a)return;if(['anchoPlano','anchoInspeccion','desdeLC','desdeLCInspeccion'].includes(key))a[key]=value===''?null:Number(value);else a[key]=value;updateDecision(e);persist();renderAccesses(false);renderMotorSelect();renderTable()}
function renderAccesses(resetClass=true){let e=expedientes.find(x=>x.id===currentInspection);if(!e)return;normalizeCase(e);$('accessList').innerHTML=e.inspection.accesos.map((a,i)=>{let ev=accessEval(a),diff=ev.difference===null?'':ev.difference.toFixed(2);return `<div class="access-card"><div class="access-head"><b>Acceso ${i+1}</b><span class="pill ${ev.className}">${ev.status}</span><div class="right-actions">${e.inspection.accesos.length>1?`<button class="btn" onclick="removeAccess(${i})">Quitar</button>`:''}</div></div><div class="access-grid"><div class="field access-type"><label>Tipo de acceso</label><select onchange="setAccess(${i},'tipo',this.value)"><option ${a.tipo==='Calle pública'?'selected':''}>Calle pública</option><option ${a.tipo==='Servidumbre de paso (Acceso excepcional)'?'selected':''}>Servidumbre de paso (Acceso excepcional)</option><option ${a.tipo==='Servidumbre agrícola'?'selected':''}>Servidumbre agrícola</option><option ${a.tipo==='Acceso al predio (callejón de acceso)'?'selected':''}>Acceso al predio (callejón de acceso)</option><option ${a.tipo==='Otro'?'selected':''}>Otro</option></select></div><div class="field"><label>Ancho según plano (m)</label><input type="number" step="0.01" value="${a.anchoPlano??''}" oninput="setAccess(${i},'anchoPlano',this.value)"></div><div class="field"><label>Ancho inspeccionado (m)</label><input type="number" step="0.01" value="${a.anchoInspeccion??''}" oninput="setAccess(${i},'anchoInspeccion',this.value)"></div><div class="field"><label>Diferencia (m)</label><input readonly value="${diff}"></div><div class="field"><label>Referencia</label><select onchange="setAccess(${i},'referencia',this.value)"><option value="ANCHO_TOTAL" ${a.referencia!=='DESDE_LC'?'selected':''}>Ancho total</option><option value="DESDE_LC" ${a.referencia==='DESDE_LC'?'selected':''}>Desde L.C.</option></select></div><div class="field access-lc"><label>Ancho desde L.C. según plano (m)</label><input type="number" step="0.01" value="${a.desdeLC??''}" oninput="setAccess(${i},'desdeLC',this.value)"></div><div class="field access-lc"><label>Ancho desde L.C. en inspección (m)</label><input type="number" step="0.01" value="${a.desdeLCInspeccion??''}" oninput="setAccess(${i},'desdeLCInspeccion',this.value)"></div><div class="field access-observation"><label>Observación</label><textarea oninput="setAccess(${i},'observacion',this.value)">${esc(a.observacion||'')}</textarea></div></div><div class="access-result ${ev.className}">${ev.complete?(ev.match?'Ancho de calle coincide con el plano.':`Diferencia registrada: ${ev.difference>0?'+':''}${ev.difference.toFixed(2)} m.`):'Falta registrar ambos anchos para comparar.'}</div></div>`}).join('');if(resetClass)$('accessList').classList.toggle('show-lc',showLCFields);let ev=inspectionEval(e);$('inspectionSummary').textContent=ev.complete?(ev.match?'CONFORME':'DIFERENCIA'):'PENDIENTE';$('inspectionSummary').className='pill '+(ev.complete?(ev.match?'green':'red'):'amber');$('inspectionOverall').textContent=ev.complete?(ev.match?'Todos los anchos registrados coinciden.':`${ev.mismatches.length} acceso(s) presentan diferencia.`):'Inspección pendiente de completar.'}
function saveInspection(){let e=expedientes.find(x=>x.id===currentInspection);if(!e)return;e.inspection.observaciones=$('inspectionObs').value;e.inspection.guardada=true;let first=e.inspection.accesos[0]||emptyAccess();e.inspection.anchoCallePlanoMadre=first.anchoPlano;e.inspection.anchoCalleInspeccion=first.anchoInspeccion;e.inspection.referenciaMedicion=first.referencia;e.inspection.distanciaDesdeLC=first.desdeLC;e.inspection.distanciaDesdeLCInspeccion=first.desdeLCInspeccion;e.inspection.acceso=first.tipo;e.inspection.diferenciaAncho=accessEval(first).difference;updateDecision(e);e.estado=e.dictamen==='PENDIENTE'?'EN INSPECCIÓN':'LISTO PARA CALIFICACIÓN';persist();renderAll();alert('Inspección guardada.')}

function inheritedReasons(e){let out=preFailures(e).map(r=>({source:'Precalificación',label:r.id,motivation:r.req,fund:r.fund||''}));let ie=inspectionEval(e);ie.mismatches.forEach(x=>{let a=e.inspection.accesos[x.index],d=x.difference;out.push({source:'Inspección',label:`Acceso ${x.index+1}`,motivation:`Ancho según plano: ${Number(a.anchoPlano).toFixed(2)} m. Ancho inspeccionado: ${Number(a.anchoInspeccion).toFixed(2)} m. Diferencia: ${d>0?'+':''}${d.toFixed(2)} m.`,fund:''})});return out}
function catalogObservation(x){return (x?.observaciones_excel||[]).map(v=>String(v||'').trim()).find(Boolean)||''}
function catalogReasons(e){return e.defectIds.map(code=>CATALOGO.find(x=>x.codigo===code)).filter(Boolean).map(x=>({source:'Calificación',label:x.codigo,motivation:x.descripcion,fund:x.fundamento_legal||'',observation:catalogObservation(x)}))}
function manualReasons(e){return (e.manualRejects||[]).map(x=>({source:'Detalle agregado',label:'Detalle',motivation:x.motivacion||x.detalle||'',fund:x.fundamento||'',detalle:x.detalle||'',observation:x.detalle||''}))}
function allRejectReasons(e){return [...inheritedReasons(e),...catalogReasons(e),...manualReasons(e)]}
function updateDecision(e){if(e.calificacionFinalizada)return {decision:e.dictamen||'APROBADO',reasons:allRejectReasons(e),inspection:inspectionEval(e),pre:preStats(e)};let reasons=allRejectReasons(e),ie=inspectionEval(e),ps=preStats(e),decision;if(!ie.complete)decision='PENDIENTE';else if(reasons.length)decision='RECHAZADO';else decision='APROBADO';e.dictamen=decision;if(decision==='APROBADO'||decision==='RECHAZADO')e.estado='LISTO PARA RESOLUCIÓN';else if(!ps.complete)e.estado='EN PRECALIFICACIÓN';else e.estado='EN INSPECCIÓN';return {decision,reasons,inspection:ie,pre:ps}}

function searchCompact(v){return foldName(v).replace(/[^a-z0-9]+/g,'')}
function catalogSearchFields(x){return [x.codigo,x.codigo_maestro,x.codigo_equivalente,...(x.codigos_fuente_excel||[]),...(x.aliases_busqueda||[]),x.descripcion,x.categoria,x.fundamento_legal,...(x.observaciones_excel||[]),...(x.resumenes_excel||[]),...(x.descripcion_tecnica_excel||[]),...(x.normas_excel||[])].filter(Boolean)}
function catalogSearchScore(x,query){let q=foldName(query);if(!q)return 1;let qc=searchCompact(query),best=0,codes=[x.codigo,x.codigo_maestro,x.codigo_equivalente,...(x.codigos_fuente_excel||[])].filter(Boolean),aliases=(x.aliases_busqueda||[]).filter(Boolean);for(const f of codes){let nf=foldName(f),cf=searchCompact(f);if(cf===qc||nf===q)best=Math.max(best,1200);else if(cf.startsWith(qc)||nf.startsWith(q))best=Math.max(best,1000);else if(cf.includes(qc)||nf.includes(q))best=Math.max(best,900);else{let d=levenshtein(cf,qc),limit=Math.max(1,Math.floor(Math.max(cf.length,qc.length)*.28));if(d<=limit)best=Math.max(best,760-d*35)}}for(const f of aliases){let nf=foldName(f);if(nf===q)best=Math.max(best,1100);else if(nf.startsWith(q))best=Math.max(best,900);else if(nf.includes(q)||q.includes(nf))best=Math.max(best,780)}let all=foldName(catalogSearchFields(x).join(' '));if(all.includes(q))best=Math.max(best,650);let tokens=q.split(' ').filter(t=>t.length>1);if(tokens.length&&tokens.every(t=>all.includes(t)))best=Math.max(best,600+Math.min(80,tokens.length*12));else if(tokens.length){let found=tokens.filter(t=>all.includes(t)).length;if(found)best=Math.max(best,300+Math.round(250*found/tokens.length))}return best}
function catalogEquivalents(x){let vals=[x.codigo_equivalente,...(x.codigos_fuente_excel||[])].filter(Boolean),base=searchCompact(x.codigo),seen=new Set;return vals.filter(v=>{let k=searchCompact(v);if(!k||k===base||seen.has(k))return false;seen.add(k);return true})}
function renderMotorSelect(){let alert=$('calAlert')?.value||'',rows=expedientes.filter(CVISADOS_WORKFLOW.isTramitesCase).filter(e=>matchesAlertFilter(e,alert));if(!rows.some(x=>x.id===currentMotor))currentMotor=rows[0]?.id??null;$('motorExp').innerHTML=options(rows,currentMotor);let cats=[...new Set(CATALOGO.map(x=>x.categoria))].sort(),v=$('defCat').value;$('defCat').innerHTML='<option value="">Todas</option>'+cats.map(x=>`<option>${esc(x)}</option>`).join('');$('defCat').value=v;if(rows.length)loadQualification(currentMotor);else{$('catalog').innerHTML='<div class="empty">Sin expedientes.</div>';$('decisionBox').textContent='PENDIENTE · Sin expedientes'}}
$('motorExp').onchange=e=>{currentMotor=Number(e.target.value);loadQualification(currentMotor)};if($('calAlert'))$('calAlert').onchange=renderMotorSelect;$('defSearch').oninput=renderCatalog;$('defCat').onchange=renderCatalog;$('calificador').onchange=()=>{let e=expedientes.find(x=>x.id===currentMotor);if(!e)return;e.calificacionEncargado=$('calificador').value;persist()};
function loadQualification(id){let e=expedientes.find(x=>x.id===Number(id));if(!e)return;currentMotor=e.id;normalizeCase(e);$('calificador').value=e.calificacionEncargado||'';renderCatalog();renderQualificationSide(e)}
function renderCatalog(){let e=expedientes.find(x=>x.id===currentMotor);if(!e)return;let q=$('defSearch').value.trim(),cat=$('defCat').value;let rows=CATALOGO.map(x=>({x,score:catalogSearchScore(x,q)})).filter(o=>(!q||o.score>0)&&(!cat||o.x.categoria===cat)).sort((a,b)=>q?(b.score-a.score||String(a.x.codigo).localeCompare(String(b.x.codigo),'es')):String(a.x.categoria).localeCompare(String(b.x.categoria),'es')||String(a.x.codigo).localeCompare(String(b.x.codigo),'es')).map(o=>o.x);let groups=[...new Set(rows.map(x=>x.categoria))];$('catalog').innerHTML=groups.length?groups.map(g=>{let items=rows.filter(x=>x.categoria===g),selected=items.filter(x=>e.defectIds.includes(x.codigo)).length;return `<details class="cat-group" ${q||selected?'open':''}><summary>${esc(g)} <span class="count">${selected}/${items.length} seleccionadas</span></summary>${items.map(x=>{let eq=catalogEquivalents(x);return `<label class="criterion" onclick="showDef('${String(x.codigo).replaceAll("'","\\'")}')"><input type="checkbox" data-code="${esc(x.codigo)}" ${e.defectIds.includes(x.codigo)?'checked':''} onclick="event.stopPropagation()"><b class="code">${esc(x.codigo)}</b><span class="desc">${esc(x.descripcion)}<div class="small">${esc(x.categoria)}${eq.length?` · Equiv.: ${esc(eq.join(' · '))}`:''}</div></span></label>`}).join('')}</details>`}).join(''):'<div class="empty">Sin causales para el filtro indicado.</div>';$('catalog').querySelectorAll('[data-code]').forEach(c=>c.onchange=()=>toggleDef(c.dataset.code,c.checked));renderQualificationSide(e)}
function showDef(code){let x=CATALOGO.find(v=>v.codigo===code);if(!x)return;let eq=catalogEquivalents(x),obs=catalogObservation(x);$('defDetail').textContent=`Código: ${x.codigo}${eq.length?'\nEquivalentes / fuente: '+eq.join(' · '):''}\nCategoría: ${x.categoria}${obs?'\n\nObservación (Excel):\n'+obs:''}\n\nDescripción:\n${x.descripcion}\n\nFundamento jurídico:\n${x.fundamento_legal}${x.alertas_fuente?.length?'\n\nAdvertencias de fuente:\n- '+x.alertas_fuente.join('\n- '):''}`}
function toggleDef(code,on){let e=expedientes.find(x=>x.id===currentMotor);if(!e)return;if(on&&!e.defectIds.includes(code))e.defectIds.push(code);if(!on)e.defectIds=e.defectIds.filter(x=>x!==code);updateDecision(e);persist();renderCatalog();renderCloseSelect();renderTable()}
function toggleManualPanel(force){let el=$('manualPanel'),open=typeof force==='boolean'?force:!el.classList.contains('open');el.classList.toggle('open',open);if(!open){$('manualDetalle').value='';$('manualMotivacion').value='';$('manualFundamento').value=''}}
function addManualReject(){let e=expedientes.find(x=>x.id===currentMotor);if(!e)return;let detalle=$('manualDetalle').value.trim(),motivacion=$('manualMotivacion').value.trim(),fundamento=$('manualFundamento').value.trim();if(!detalle&&!motivacion&&!fundamento){alert('Ingrese el detalle de rechazo.');return}e.manualRejects.push({id:Date.now(),detalle,motivacion,fundamento,fecha:new Date().toISOString()});updateDecision(e);persist();toggleManualPanel(false);renderCatalog();renderCloseSelect();renderTable()}
function removeManualReject(id){let e=expedientes.find(x=>x.id===currentMotor);if(!e)return;e.manualRejects=e.manualRejects.filter(x=>x.id!==id);updateDecision(e);persist();renderCatalog();renderCloseSelect();renderTable()}
function renderQualificationSide(e){let state=updateDecision(e),inh=inheritedReasons(e),manual=e.manualRejects||[];$('decisionBox').className='statusbox '+(state.decision==='APROBADO'?'green':state.decision==='RECHAZADO'?'red':'amber');$('decisionBox').textContent=state.decision==='APROBADO'?'APROBADO · Sin motivos de rechazo':state.decision==='RECHAZADO'?`RECHAZADO · ${state.reasons.length} motivo(s)`:'PENDIENTE · Complete la inspección';$('flowSummary').innerHTML=[`<span class="flow-chip ${state.pre.complete?'green':'red'}">Precalificación ${state.pre.ok}/${state.pre.total}</span>`,`<span class="flow-chip ${state.inspection.complete?(state.inspection.match?'green':'red'):'amber'}">Inspección ${state.inspection.complete?(state.inspection.match?'conforme':'con diferencia'):'pendiente'}</span>`,`<span class="flow-chip ${e.defectIds.length?'red':'green'}">Calificación ${e.defectIds.length} causal(es)</span>`].join('');$('inheritedRejects').innerHTML=inh.length?inh.map(x=>`<div class="inherited-item"><span class="inherited-tag">${esc(x.source)}</span><b>${esc(x.label)}</b><div>${esc(x.motivation)}</div>${x.fund?`<div class="small">${esc(x.fund)}</div>`:''}</div>`).join(''):'Sin incumplimientos heredados.';$('manualRejectList').innerHTML=manual.length?manual.map(x=>`<div class="manual-item"><button class="btn actions" onclick="removeManualReject(${x.id})">Quitar</button><b>${esc(x.detalle||'Detalle agregado')}</b>${x.motivacion?`<div>${esc(x.motivacion)}</div>`:''}${x.fundamento?`<div class="small">${esc(x.fundamento)}</div>`:''}</div>`).join(''):'Ninguno.';$('selectedDefs').innerHTML=e.defectIds.length?e.defectIds.map(code=>{let x=CATALOGO.find(v=>v.codigo===code),obs=catalogObservation(x);return `<div class="selected-reason"><b>✓ ${esc(code)}</b><div>${esc(x?.descripcion||'')}</div>${obs?`<div class="selected-observation"><b>Observación:</b> ${esc(obs)}</div>`:''}</div>`}).join(''):'Sin causales seleccionadas.';$('selectedCount').textContent=String(e.defectIds.length);$('selectedCount').className='right pill '+(e.defectIds.length?'red':'green')}
function saveQualification(){let e=expedientes.find(x=>x.id===currentMotor);if(!e)return;e.calificacionEncargado=$('calificador').value.trim();let state=updateDecision(e);if(state.decision==='PENDIENTE'){alert('No se puede finalizar la calificación: complete la inspección antes de enviarla a Resoluciones.');return}if(state.decision==='RECHAZADO'&&!state.reasons.length){alert('Un rechazo requiere defectos o motivos registrados.');return}if(!confirm(`Guardar, finalizar y enviar ${caseRef(e)} a Resoluciones como ${state.decision}?`))return;CVISADOS_WORKFLOW.finishQualification(e,{decision:state.decision,reasons:state.reasons,now:new Date().toISOString()});appendQualificationObservation(e,state.decision);persist();currentClose=e.id;renderAll();alert(`Calificación finalizada y enviada a Resoluciones: ${state.decision}.`);go('cierre')}
function appendQualificationObservation(e,decision){let text=`Calificación finalizada y enviada a Resoluciones: ${decision}.`;e.observacionesHistorial=Array.isArray(e.observacionesHistorial)?e.observacionesHistorial:[];e.observacionesHistorial.push({modulo:'Calificación',observacion:text,fecha:new Date().toISOString()})}
function renderCloseSelect(){let rows=expedientes.filter(CVISADOS_WORKFLOW.isResolutionCase);if(!rows.some(x=>x.id===currentClose))currentClose=rows[0]?.id??null;$('closeExp').innerHTML=options(rows,currentClose);if(rows.length)loadClose(currentClose);else{$('closeStatus').textContent='SIN EXPEDIENTES';$('reportFrame').srcdoc='';$('finalBtn').disabled=true;$('reopenBtn').disabled=true}}$('closeExp').onchange=e=>{currentClose=Number(e.target.value);loadClose(currentClose)};
